 export type WebhookResponse = { status: number; body: string };

+const BAD_REQUEST: WebhookResponse = { status: 400, body: "invalid payload" };
+
+function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+// Contract: docs/provider.md. Returns undefined if the data can never be accepted.
+function parsePayment(data: unknown): Payment | undefined {
+  if (!isRecord(data)) return undefined;
+  const { id, amount_cents: amountCents, currency } = data;
+  if (typeof id !== "string" || !id.startsWith("pay_")) return undefined;
+  if (typeof amountCents !== "number" || !Number.isSafeInteger(amountCents) || amountCents < 0) return undefined;
+  if (typeof currency !== "string" || !/^[A-Z]{3}$/.test(currency)) return undefined;
+  return { id, amountCents, currency };
+}
+
 export function handleWebhook(rawBody: string): WebhookResponse {
-  const event = JSON.parse(rawBody) as {
-    type: string;
-    data: { id: string; amount_cents: number; currency: string };
-  };
+  let event: unknown;
+  try {
+    event = JSON.parse(rawBody);
+  } catch {
+    return BAD_REQUEST;
+  }
+  if (!isRecord(event) || typeof event.type !== "string") return BAD_REQUEST;
   if (event.type !== "payment.succeeded") return { status: 200, body: "ignored" };
-  const payment: Payment = {
-    id: event.data.id,
-    amountCents: event.data.amount_cents,
-    currency: event.data.currency,
-  };
+
+  const payment = parsePayment(event.data);
+  if (!payment) return BAD_REQUEST;
   recordPayment(payment);
   return { status: 200, body: "ok" };
 }
